namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class JeanPaulSartre
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Les vraies dames ne savent pas le prix des choses, elles aiment les belles folies; leurs yeux sont de belles fleurs candides, des fleurs de serre.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "J'existe parce que je pense…", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je trouve, dis-je à l'Autodidacte, qu'on ne peut pas plus haïr les hommes que les aimer.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "C'est ça donc la Nausée : cette aveuglante évidence ? Me suis-je creusé la tête ! En ai-je écrit ! Maintenant je sais : j'existe — le monde existe — et je sais que le monde existe. C'est tout. Mais ça m'est égal. C'est étrange que tout me soit aussi égal : ça m'effraie.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Exister, c'est être là, simplement ; les existants apparaissent, se laissent rencontrer, mais on ne peut jamais les déduire.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Tout existant naît sans raison, se prolonge par faiblesse et meurt par rencontre.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Du même coup, j'ai appris qu'on perd toujours. Il n'y a que les Salauds qui croient gagner.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Son nez était planté dans son visage comme un couteau dans une pomme.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "C'est ce jour-là, à cette heure-là que tout a commencé. Et j'arriverais — au passé, rien qu'au passé — à m'accepter.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Quelques heures ou quelques années d'attente c'est tout pareil, quand on a perdu l'illusion d'être éternel.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "C'est à partir du jour où l'on peut concevoir un autre état de choses qu'une lumière neuve tombe sur nos peines et sur nos souffrances et que nous décidons qu'elles sont insupportables.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Chaque regard nous fait éprouver concrètement […] que nous existons pour tous les hommes vivants.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Jamais nous n'avons été plus libres que sous l'occupation allemande.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je n'ai pas rêvé cet héroïsme. Je l'ai choisi. On est ce qu'on veut.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Seuls les actes décident de ce qu'on a voulu.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "On meurt toujours trop tôt — ou trop tard. Et cependant la vie est là, terminée […]. Tu n'es rien d'autre que ta vie.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Alors, c'est ça l'enfer. Je n'aurais jamais cru… Vous vous rappelez : le soufre, le bûcher, le gril… Ah ! quelle plaisanterie. Pas besoin de gril : l'enfer, c'est les Autres.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "L'existence précède l'essence.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "L'homme est condamné à être libre.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Moi j'ai les mains sales. Jusqu'aux coudes. Je les ai trempées dans la merde et dans le sang.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Salut petit frère ! Salut en bâtardise ! Car toi aussi tu es un bâtard ! Pour t'engendrer, le clergé a couché avec Misère ; quelle maussade volupté !", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je me moque du Diable ! Il reçoit les âmes, mais ce n'est pas lui qui les damne. Je ne daigne avoir affaire qu'à Dieu, les monstres et les saints ne relèvent que de lui.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Mais vous approuviez la clémence de l'Archevêque ! Et je l'approuve encore. Il est offensé et prêtre : deux bonnes raisons de pardonner. Mais moi, pourquoi pardonnerais-je ? Les habitants de Worms ne m'ont pas offensé. Non, non : je suis militaire, donc je tue. Je les tuerai conformément à mon office et l'Archevêque leur pardonnera, conformément au sien", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "De quoi te mêles-tu ? (Un temps.) Le mal, ça doit faire mal à tout le monde. Et d'abord à celui qui le fait.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Alors réjouis-toi, je la prendrai. Mais pourquoi ? Parce que c'est mal. Et pourquoi faire le Mal ? Parce que le Bien est déjà fait. Qui l'a fait ? Dieu le Père. Moi, j'invente.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Les hommes de Dieu détruisent ou construisent et toi tu conserves. Moi ? Tu mets du désordre. Et le désordre est le meilleur serviteur de l'ordre établi. Tu as affaibli la chevalerie tout entière en trahissant Conrad et tu affaibliras la bourgeoisie en détruisant Worms. À qui cela profite-t-il ? Aux grands. Tu sers les grand, Gœtz, et tu les serviras quoi que tu fasses : toute destruction brouillonne, affaiblit les faibles, enrichit les riches, accroît la puissance des puissants.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "L'égal de tous les hommes ou le valet de tous les princes : choisis.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Inutile, oui. Inutile aux hommes. Mais que me font les hommes ? Dieu m'entend et c'est à Dieu que je casse les oreilles et ça me suffit, car c'est le seul ennemi qui soit digne de moi. Il y a Dieu, moi et les fantômes. C'est Dieu que je crucifierai cette nuit, sur toi et sur vingt mille hommes parce que sa souffrance est infinie et qu'elle rend infini celui qui le fait souffrir. Cette ville va flamber. Dieu le sait. Et en ce moment, il a peur, je le sens ; je sens son regard sur mes mains, je sens son souffle sur mes cheveux, ses anges pleurent. Il se dit « Gœtz n'osera peut-être pas » — tout comme s'il n'était qu'un homme. Pleurez, pleurez les anges : j'oserai. Tout à l'heure, je marcherai dans sa peur et dans sa colère. Elle flambera : l'âme du Seigneur est une galerie de glaces, le feu s'y reflétera dans des millions de miroirs. Alors, je saurai que je suis un monstre tout à fait pur.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Le monde est iniquité ; si tu l'acceptes tu es complice, si tu le changes, tu es bourreau.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Le Bien, c'est l'amour, bon : mais le fait est que les hommes ne s'aiment pas ; et qu'est-ce qui les en empêche ? L'inégalité des conditions, la servitude et la misère. Il faut donc les supprimer.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je ne serai pas modeste. Humble tant qu'on voudra, mais pas modeste. La modestie est la vertu des tièdes.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Heinrich disait « il a suffi que deux hommes se haïssent pour que la haine, de proche en proche, gagne tout l'univers. » Et moi, je dis, en vérité il suffit qu'un homme aime tous les hommes d'un amour sans partage pour que cet amour s'étende de proche en proche à toute l'humanité.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je sais que le Bien est plus pénible que le Mal. Le Mal ce n'était que moi, le Bien c'est tout.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Encore le jeu du pardon ? (Un temps.) C'est un jeu qui m'ennuie : je ne suis pas dans le coup. Je n'ai qualité ni pour condamner ni pour absoudre : c'est l'affaire de Dieu.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je ne veux pas que tu te réjouisses d'avoir mis des hommes à quatre pattes.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Par ma faute… Rien, je sonne creux. Tu veux de la honte, je n'en ai pas. C'est l'orgueil qui suinte de toutes mes plaies : depuis trente-cinq ans je crève d'orgueil, c'est ma façon de mourir de honte. Il faudra changer ça. (Brusquement.) Ôte-moi la pensée ! Ôte-la ! Fais que je m'oublie ! Change moi en insecte ! Ainsi soit-il !", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Pour moi, je ne sais pas ce que tu me réserves, je ne la connaissais guère mais si tu la condamnes, je ne veux pas de ton ciel. Crois-tu que mille ans de paradis me ferait oublier la terreur de ses yeux ? Je n'ai que mépris pour les élus imbéciles qui ont le cœur de se réjouir quand il y a des damnés en enfer et des pauvres sur la terre ; moi je suis du parti des hommes et je ne le quitterai pas ; tu peux me faire mourir sans prêtre et me convoquer par surprise à ton tribunal : nous verrons qui jugera l'autre.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Vous aussi, le Diable vous guette. Qui donc aura pitié de vous si vous n'avez pas pitié d'elle ? Qui donc aimera les pauvres si les pauvres ne s'aiment pas entre eux ?", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Bravo ! Laissez les donc s'entre-tuer. La haine, les massacres, le sang des autres sont les aliments nécessaires de votre bonheur.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Plus ils m'aiment et plus je suis seul. Je suis leur toit et je n'ai pas de toit. Je suis leur ciel et je n'ai pas de ciel. Si, j'en ai un : celui-ci, vois comme il est loin. Je voulais me faire pilier et porter la voûte céleste. Je t'en fous : le ciel est un trou. Je me demande même où Dieu loge. (un temps) Je ne les aime pas assez : tout vient de là. J'ai fait les gestes de l'amour mais l'amour n'est pas venu : il faut croire que je ne suis pas doué.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Nasty , il faut pendre des pauvres. Les pendre au hasard, pour l'exemple : l'innocent avec le coupable. Que dis-je ? Ils sont tous innocents. Aujourd'hui je suis leur frère et je vois leur innocence. Demain, si je suis leur chef, il n'y a plus que des coupables et je ne comprends plus rien : je pends.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Qui es-tu ? Prophète comme toi. Prophète de haine ! C'est le seul chemin qui mène à l'amour.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Les terres sont à vous : celui qui prétend vous les donner vous dupe, car il donne ce qui n'est pas à lui. Prenez-les ! Prenez et tuez, si vous voulez devenir des hommes. C'est par la violence que nous nous éduquerons.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Et voilà, mon Dieu : nous sommes de nouveau face à face, comme au bon vieux temps où je faisais le mal. Ah ! Je n'aurais jamais dû m'occuper des hommes : ils gênent. Ce sont des broussailles qu'il faut écarter pour parvenir à toi. Je viens à toi, Seigneur, je viens, je marche dans la nuit : donne moi la main. Dis : La nuit, c'est toi, hein ? La nuit, l'absence déchirante de tout ! Car tu es celui qui est présent dans l'universelle absence, celui qu'on entend quand tout est silence, celui qu'on voit quand on ne voit plus rien. Vieille nuit, grande nuit d'avant les êtres, nuit de la disgrâce et du malheur, cache-moi, dévore mon corps immonde, glisse-toi entre mon âme et moi-même et ronge-moi.Je veux le dénuement, la honte et la solitude du mépris, car l'homme est fait pour détruire l'homme en lui-même et pour s'ouvrir comme une femelle au grand corps noir de la nuit. Jusqu'à ce que je goûte à tout, je n'aurai plus de goût à rien, jusqu'à ce que je possède tout, je ne possèderai plus rien. Jusqu'à ce que je sois tout, je ne serai plus rien en rien. Je m'abaisserai au-dessous de tous et, Seigneur, tu me prendras dans les filets de ta nuit et tu m'élèveras au-dessus d'eux.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Nous n'irons pas au ciel, Gœtz, et même si nous y entrions tous les deux, nous n'aurions pas d'yeux pour nous voir, pas de mains pour nous toucher. Là-haut, on ne s'occupe que de Dieu. (Elle vient le toucher) Tu es là : un peu de chair usée, rugueuse, misérable, une vie — une pauvre vie. C'est cette chair et cette vie que j'aime. On ne peut aimer que sur cette terre et contre Dieu.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Ces trois philosophies [Descartes/Locke, Kant/Hegel, Marx] deviennent, chacune à son tour, l’humus de toute pensée particulière et l’horizon de toute culture, elles sont indépassables tant que le moment historique dont elles sont l’expression n’a pas été dépassé.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Nul doute que cette anémie pratique devienne une anémie de l’homme marxiste – c’est à dire de nous, hommes du XXe siècle, en tant que le cadre indépassable du Savoir est le marxisme et en tant que ce marxisme éclaire notre praxis individuelle et collective, donc nous détermine dans notre existence.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Le Progrès, ce long chemin ardu qui mène jusqu'à moi.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Qu'ils écoutent mon babillage ou l'art de la fugue, les adultes ont le même sourire de dégustation malicieuse et de connivence ; cela montre ce que je suis au fond : un bien culturel. La culture m'imprègne et je la rends à la famille par rayonnement, comme les étangs, au soir, rendent la chaleur du jour.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je traite les inférieurs en égaux : c'est un pieux mensonge que je leur fais pour les rendre heureux et dont il convient qu'ils soient dupes jusqu'à un certain point. A ma bonne, au facteur, à ma chienne, je parle d'une voix patiente et tempérée. Dans ce monde en ordre il y a des pauvres. Il y a aussi des moutons à cinq pattes, des sœurs siamoises, des accidents de chemin de fer : ces anomalies ne sont la faute de personne. Les bons pauvres ne savent pas que leur office est d'exercer notre générosité ; ce sont des pauvres honteux, ils rasent les murs ; je m'élance, je leur glisse dans la main une pièce de deux sous et, surtout, je leur fais cadeau d'un beau sourire égalitaire. Je trouve qu'ils ont l'air bête et je n'aime pas les toucher mais je m'y force : c'est une épreuve ; et puis il faut qu'ils m'aiment : cet amour embellira leur vie. Je sais qu'ils manquent du nécessaire et il me plaît d'être leur superflu.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Le génie n'est qu'un prêt : il faut le mériter par de grandes souffrances, par des épreuves modestement, fermement traversées.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "J'avais vu les romans d'aventures, je les avais convoités, réclamés, pouvait elle me les refuser ? […] À lui de choisir : ou je ne prophétisais point, ou l'on devait respecter mes goûts sans chercher à les comprendre. Père, Charles Schweitzer eût tout brûlé. Grand-père, il choisit l'indulgence navrée. Je n'en demandais pas plus et je continuai paisiblement ma double vie. Elle n'a jamais cessé : aujourd'hui encore, je lis plus volontiers les « Série Noire » que Wittgenstein.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Un jour, je découvris une inscription toute fraîche sur le mur de l'école, je m'approchai et je lus : « le père Barrault est un con. » Mon cœur battit à se rompre, la stupeur me cloua sur place, j'avais peur. « Con », ça ne pouvait être qu'un de ces « vilains mots » qui grouillaient dans les bas-fonds du vocabulaire et qu'un enfant bien élevé ne rencontre jamais; court et brutal, il avait l'horrible simplicité bébête élémentaires. C'était déjà trop de l'avoir lu : je m'interdis de le prononcer, fût-ce à voix basse. Ce cafard accroché à la muraille, je ne voulais pas qu'il me sautât dans la bouche pour se métamorphoser au fond de ma gorge en un claironnement noir. Si je faisais semblant de ne pas avoir remarqué, peut-être rentrerait-il dans un trou de mur. Mais, quand je détournais mon regard, c'était pour retrouver l'appellation infâme : « le père Barrault » qu'il épouvantait plus encore : le mot « con », après tout, je ne faisais qu'en augurer le sens ; mais je savais très bien qui on appelait « père untel » dans ma famille : les jardiniers, les facteurs, le père de la bonne, bref les vieux pauvres. [...] Il me semblait à la fois qu'un fou cruel raillait ma politesse, mon respect, mon zèle, le plaisir que j'avais chaque matin à ôter ma casquette en disant « bonjour, Monsieur l'instituteur » et que j'étais moi-même ce fou, que les vilains mots et les vilaines pensées pullulaient dans mon cœur. Qu'est-ce qui m'empêchait, par exemple, de crier plein gosier : « ce vieux sagouin pue comme un cochon. » Je murmurai : « le père Barrault pue » et tout se mit à tourner : je m'enfuis en pleurant. Dès le lendemain je retrouvai ma déférence pour M. Barrault, pour son col de celluloïd et son nœud à papillon.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Faute de renseignements plus précis, personne, à commencer par moi, ne savait ce que j'étais venu foutre sur terre.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Mais, par la suite, dans le Dieu fashionable qu'on m'enseigna, je ne reconnus pas celui qu'attendait mon âme : il me fallait un Créateur, on me donnait un Grand Patron ; les deux n'étaient qu'un mais je l'ignorais ; je servais sans chaleur l'Idole pharisienne et la doctrine officielle me dégoûtait de chercher ma propre foi.[…] Une seule fois, j'eus le sentiment qu'Il existait. J'avais joué avec des allumettes et brûlé un petit tapis; j'étais en train de maquiller mon forfait quand soudain Dieu me vit, je sentis Son regard à l'intérieur de ma tête et sur mes mains ; je tournoyais dans la salle de bains, horriblement visible, une cible vivante. L'indignation me sauva : je me mis en fureur contre une indiscrétion si grossière, je blasphémai, je murmurai comme mon grand-père : « Sacré nom de Dieu de nom de Dieu. » Il ne me regarda plus jamais.[…]. Aujourd'hui, quand on me parle de Lui, je dis avec l'amusement sans regret d'un vieux beau qui rencontre une ancienne belle : « Il y a cinquante ans, sans ce malentendu, sans cette méprise, sans l'accident qui nous sépara, il aurait pu y avoir quelque chose entre nous ». Il n'y eut rien.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Plus absurde est la vie, moins supportable la mort.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Elle ne croyait à rien; seul, son scepticisme l'empêchait d'être athée.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "En sa présence, j'avais autrefois demandé la permission de lire Madame Bovary et ma mère avais pris de sa voix trop musicale : « Mais si mon petit chéri lit ce genre de livre à son âge, qu'est-ce qu'il fera quand il sera grand ? » - « Je les vivrai ! » Cette réplique avait connu le succès le plus franc et le plus durable.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "La glace m'avait appris ce que je savais depuis toujours : j'étais horriblement naturel. Je ne m'en suis jamais remis.", Author = "Jean-Paul Sartre" },
        };
    }
}